"""Syntax + structural validation for the draft order-to-cash workflow.

Checks: YAML parses, required top-level keys, step types, task handlers,
on-fail references, and output branches. Also does a deep recursive scan
so EVERY PLACEHOLDER_* string is reported as a warning, keeping validation
coverage in sync with PLACEHOLDERS.md. Warnings are expected for a draft;
errors are not.
"""
import sys
import yaml

PATH = 'workflows/order-to-cash/workflow.yml'

with open(PATH) as f:
    doc = yaml.safe_load(f)

errors, warnings = [], []

def find_placeholders(node, path=''):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from find_placeholders(v, f'{path}.{k}')
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from find_placeholders(v, f'{path}[{i}]')
    elif isinstance(node, str) and node.startswith('PLACEHOLDER_'):
        yield path.lstrip('.'), node

expected = {'name', 'version', 'description', 'trigger', 'inputs', 'steps', 'outputs'}
missing = expected - set(doc)
if missing:
    errors.append(f"missing top-level keys: {sorted(missing)}")

for path, key in find_placeholders(doc):
    warnings.append(f"{path}: unresolved ({key})")

valid_types = {'task', 'timer-wait', 'policy'}
step_names = []
for name, s in (doc.get('steps') or {}).items():
    step_names.append(name)
    if s.get('type') not in valid_types:
        errors.append(f"step '{name}': unknown type '{s.get('type')}'")
    if s.get('type') == 'task' and 'handler' not in s:
        errors.append(f"step '{name}': task without handler")

steps_set = set(step_names)
for name, s in (doc.get('steps') or {}).items():
    ref = s.get('on-fail')
    if ref and ref not in steps_set:
        errors.append(f"step '{name}': on-fail references unknown step '{ref}'")

outputs = str(doc.get('outputs', {}).get('status', ''))
for branch in ['completed', 'rejected-invalid', 'rejected-credit']:
    if branch not in outputs:
        errors.append(f"outputs.status missing branch '{branch}'")

print(f"File: {PATH}")
print(f"Steps found: {len(step_names)} -> {step_names}")
print(f"Errors: {len(errors)}")
for e in errors:
    print(f"  ERROR: {e}")
print(f"Warnings (expected for draft): {len(warnings)}")
for w in warnings:
    print(f"  WARN: {w}")
print("RESULT:", "STRUCTURALLY VALID (draft placeholders pending)" if not errors else "INVALID")
sys.exit(1 if errors else 0)
